function applyStaffPortrait(m, c) {
  if (!c || typeof c !== "object") return false;
  const known = c.found !== false;
  if (known && c.name && cleanStr(c.name, 80).length >= 3) m.name = cleanStr(c.name, 80);
  const a = Number(c.age);
  if (known && a >= 25 && a <= 85) m.age = Math.round(a);
  else if (!m.age) m.age = 45;
  if (known && c.nationality) m.nationality = cleanStr(c.nationality, 40);
  else if (!m.nationality) m.nationality = "\u0420\u043E\u0441\u0441\u0438\u044F";
  m.specialty = cleanStr(c.specialty, 300) || m.specialty || (STAFF_ROLES[m.role]?.desc || "");
  m.bio = cleanStr(c.bio, 1200) || m.brief || m.bio || "";
  if (m.role === "head") {
    if (["possession", "press", "counter", "attack", "bus"].includes(c.style)) m.style = c.style;
    if (c.styleTitle) m.styleTitle = cleanStr(c.styleTitle, 80);
    if (/^\d(-\d){1,3}$/.test(String(c.favoriteFormation || "").trim())) m.favoriteFormation = String(c.favoriteFormation).trim();
    const r = Number(c.reputation);
    if (r >= 50 && r <= 99) m.reputation = Math.round(r);
    if (c.temperament) m.temperament = cleanStr(c.temperament, 60);
    if (c.quote) m.quote = cleanStr(c.quote, 200);
  }
  m.pending = false;
  m.verified = known;
  m.portraitAt = (/* @__PURE__ */ new Date()).toISOString();
  m.updatedAt = m.portraitAt;
  return true;
}
function buildAnalyticalStaffPortrait(m) {
  const tm = m.teamId ? team(m.teamId) : null;
  const clubName = tm?.name || "Клуб";
  const roleMeta = STAFF_ROLES[m.role] || STAFF_ROLES.head;
  m.nationality = m.nationality || "Россия";
  m.age = m.age || 45;
  m.specialty = m.specialty || roleMeta?.desc || "Организация тренировочного процесса";
  m.bio = m.bio || `${m.name} входит в тренерский штаб команды «${clubName}». Отвечает за профессиональную подготовку и командную сыгранность.`;
  if (m.role === "head") {
    m.style = m.style || "possession";
    m.styleTitle = m.styleTitle || "Сбалансированный и дисциплинированный футбол";
    m.favoriteFormation = m.favoriteFormation || "4-3-3";
    m.reputation = m.reputation || 70;
    m.temperament = m.temperament || "Уравновешенный";
    m.quote = m.quote || "«Только дисциплина, тактический порядок и самоотдача приносят победы».";
  }
  m.pending = false;
  m.verified = true;
  m.portraitAt = (/* @__PURE__ */ new Date()).toISOString();
  m.updatedAt = m.portraitAt;
  return true;
}

async function staffPortrait(m) {
  if (hasLLM()) {
    try {
      const tm = team(m.teamId);
      const meta = STAFF_ROLES[m.role] || {};
      const prompt = `\u0421\u043F\u0435\u0446\u0438\u0430\u043B\u0438\u0441\u0442: ${m.name}. \u0414\u043E\u043B\u0436\u043D\u043E\u0441\u0442\u044C: ${meta.title || m.role}.${tm ? ` \u041A\u043B\u0443\u0431 \u0432 \u0441\u0438\u043C\u0443\u043B\u044F\u0442\u043E\u0440\u0435: ${tm.name}.` : ""}${m.nationality ? ` \u0413\u0440\u0430\u0436\u0434\u0430\u043D\u0441\u0442\u0432\u043E: ${m.nationality}.` : ""}${m.age ? ` \u0412\u043E\u0437\u0440\u0430\u0441\u0442: ${m.age}.` : ""}\n\u041A\u0440\u0430\u0442\u043A\u0430\u044F \u0438\u043D\u0444\u043E\u0440\u043C\u0430\u0446\u0438\u044F \u043E\u0442 \u043A\u043B\u0443\u0431\u0430: ${m.brief || "\u2014 \u043D\u0435 \u0443\u043A\u0430\u0437\u0430\u043D\u0430"}.\n\u0421\u043E\u0441\u0442\u0430\u0432\u044C \u043F\u043E\u0440\u0442\u0440\u0435\u0442.`;
      const grounded = provList()[0]?.n === "gemini";
      const r = await llmJSON(STAFF_SYS, prompt, { task: "portrait", temp: 0.3, max: 2e3, grounded });
      const applied = applyStaffPortrait(m, Array.isArray(r?.players) ? r.players[0] : r);
      if (applied) return true;
    } catch (e) {
      console.log("[Portrait Fallback] staffPortrait falling back to analytical staff generator");
    }
  }
  return buildAnalyticalStaffPortrait(m);
}

app.post("/api/admin/staff/portrait", admin, async (req, res) => {
  const m = (db.staff || []).find((x) => x.id === req.body.id);
  if (!m) return fail(res, "\u0421\u043F\u0435\u0446\u0438\u0430\u043B\u0438\u0441\u0442 \u043D\u0435 \u043D\u0430\u0439\u0434\u0435\u043D");
  try {
    await staffPortrait(m);
    save();
    res.json({ ok: 1, member: m });
  } catch (e) {
    buildAnalyticalStaffPortrait(m);
    save();
    res.json({ ok: 1, member: m, fallback: true });
  }
});
app.post("/api/admin/staff/portraits-all", admin, async (req, res) => {
  let list = (db.staff || []).filter((x) => req.body.all ? true : x.pending);
  if (req.body.teamId) list = list.filter((x) => x.teamId === req.body.teamId);
  const total = list.length;
  list = list.slice(0, 25);
  let updated = 0, failed = 0;
  for (const m of list) {
    try {
      await staffPortrait(m);
      updated++;
    } catch {
      failed++;
    }
    save();
  }
  res.json({ ok: 1, updated, failed, left: Math.max(0, total - list.length) });
});
